//! Round-trip tests: every extracted image must match its SHA-256 from tests/fixtures/manifest.tsv.
//! Fixtures are generated by tools/make_fixtures.py (run before `cargo test`).

use anyhow::Result;
use fwx::{extract_images, list_images, Events};
use sha2::{Digest, Sha256};
use std::collections::{HashMap, HashSet};
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures")
}

#[derive(Default)]
struct Collect {
    hashes: HashMap<String, String>,
    logs: Vec<String>,
}

impl Events for Collect {
    fn log(&mut self, message: &str) {
        self.logs.push(message.to_owned());
    }

    fn image(&mut self, name: &str, path: &Path) -> Result<()> {
        let digest = Sha256::digest(fs::read(path)?);
        let hex: String = digest.iter().map(|b| format!("{b:02x}")).collect();
        self.hashes.insert(name.to_owned(), hex);
        Ok(())
    }
}

fn manifest() -> HashMap<String, HashMap<String, String>> {
    let text = fs::read_to_string(fixtures().join("manifest.tsv"))
        .expect("run tools/make_fixtures.py first");
    let mut map: HashMap<String, HashMap<String, String>> = HashMap::new();
    for line in text.lines().filter(|l| !l.is_empty()) {
        let cols: Vec<&str> = line.split('\t').collect();
        map.entry(cols[0].to_owned())
            .or_default()
            .insert(cols[1].to_owned(), cols[2].to_owned());
    }
    map
}

fn check_firmware(fw: &str, expected: &HashMap<String, String>) {
    let path = fixtures().join(fw);
    let cancel = AtomicBool::new(false);

    let listed = list_images(File::open(&path).unwrap(), fw, &cancel).unwrap();
    assert_eq!(listed.len(), expected.len(), "{fw}: number of lz4 images found");

    let selected: HashSet<String> = listed.iter().map(|i| i.path.clone()).collect();
    let work = std::env::temp_dir().join(format!("fwx-test-{}-{fw}", std::process::id()));
    let mut events = Collect::default();
    extract_images(File::open(&path).unwrap(), fw, &selected, &work, &mut events, &cancel).unwrap();
    let _ = fs::remove_dir_all(&work);

    assert_eq!(events.hashes.len(), expected.len(), "{fw}: number of images written");
    for (name, want) in expected {
        let got = events.hashes.get(name).unwrap_or_else(|| panic!("{fw}: missing {name}"));
        assert_eq!(got, want, "{fw}: hash mismatch for {name}");
    }
}

#[test]
fn samsung_zip_with_nested_tars() {
    let m = manifest();
    check_firmware("SAMSUNG_TEST.zip", &m["SAMSUNG_TEST.zip"]);
}

#[test]
fn ap_tar_md5() {
    let m = manifest();
    check_firmware("AP_TEST.tar.md5", &m["AP_TEST.tar.md5"]);
}

#[test]
fn loose_lz4() {
    let m = manifest();
    check_firmware("loose.img.lz4", &m["loose.img.lz4"]);
}

#[test]
fn cancellation_stops_extraction() {
    let cancel = AtomicBool::new(true);
    let selected: HashSet<String> = ["loose.img.lz4".to_owned()].into_iter().collect();
    let work = std::env::temp_dir().join(format!("fwx-cancel-{}", std::process::id()));
    let mut events = Collect::default();
    let res = extract_images(
        File::open(fixtures().join("loose.img.lz4")).unwrap(),
        "loose.img.lz4",
        &selected,
        &work,
        &mut events,
        &cancel,
    );
    let _ = fs::remove_dir_all(&work);
    assert!(res.is_err());
    assert!(events.hashes.is_empty());
}
